import{_ as t,c as n,o as s,j as a,a as l}from"./chunks/framework.BKeRpnBD.js";const _=JSON.parse('{"title":"易纂言卷十一","description":"易纂言 - 易纂言卷十一","frontmatter":{"title":"易纂言卷十一","description":"易纂言 - 易纂言卷十一"},"headers":[],"relativePath":"classics/zuanyan/012.md","filePath":"classics/zuanyan/012.md"}'),r={name:"classics/zuanyan/012.md"};function c(o,e,i,p,d,u){return s(),n("div",null,[...e[0]||(e[0]=[a("h1",{id:"易纂言卷十一",tabindex:"-1"},[l("易纂言卷十一 "),a("a",{class:"header-anchor",href:"#易纂言卷十一","aria-label":"Permalink to “易纂言卷十一”"},"​")],-1),a("p",null,"欽定四庫全書",-1),a("p",null,"元吳澄撰",-1),a("p",null,"序卦傳 羲皇六十四卦之序，始乾終坤。蓋奇畫耦畫之上，每加一奇一耦，二而四，四而八，八而十六，十六而三十二，以極於六十四，乃其生卦自然之序，非人所安排也。後之易，各因羲皇之卦，而其序不同。如連山之首艮，歸藏之首坤，不復可知其六十四卦之序何如矣。始乾、坤，終既濟、未濟者，周易六十四卦之序也。蓋文王既立卦名之後，而次其先後之序如此，皆以施用於人事者起義，而夫子為之傳，以發明其卦序之意。或者乃疑其非夫子之作。張子曰：序卦不可謂非聖人之蘊，其間雖無極至精義，大槩皆有意思。今欲安置一物，猶求審處，況聖人之於易，必須布遍精密如是，大匠豈以一斧可知哉！",-1),a("p",null,"有天地，然後萬物生焉。 此言乾坤所以為上經之首也。天地，謂乾、坤二卦。 盈天地之間者唯萬物，故受之以屯。屯者，盈也。屯者，物之始生也。 此言屯所以次乾坤也。盈者，窒塞填滿之意也。始生艱難，未能暢達，如人慾吐未吐，欲瀉未瀉，窒塞填滿於中。程子曰：天地生萬物，萬物之始生，鬱結未通，盈塞於天地之間，故繼乾坤之後。 物生必蒙，故受之以蒙。蒙者，蒙也，物之稚也。 此言「蒙」所以次屯也。程子曰：屯，物之始生，稚小蒙昩。 物稚不可不養也，故受之以需。需者，飲食之道也。 此言「需」所以次「蒙」也。程子曰：物之幼稚，必待養而成。養物之需者，飲食也。飲食所以潤益於物。雲上於天，有蒸潤之象，故需為飲食之道。 飲食必有訟，故受之以訟。 此言「訟」所以次「需」也。程子曰：人之所需者飲食。既有所需，爭訟所由起。 訟必有眾起，故受之以師。師者，眾也。 此言「師」所以次「訟」也。程子曰：師之興，猶有爭也。 眾必有所比，故受之以比。比者，比也。 此言「比」所以次「師」也。程子曰：比，親輔也。既有眾，必相親輔，然後能安。 比必有所畜，故受之以小畜。 此言「小畜」所以次「比」也。程子曰：物相比輔，則為聚畜。 物畜然後有禮，故受之以履。履者，禮也。 此言履所以次「小畜」也。程子曰：物之聚，則有大小之別，高下之等，美惡之分。是物畜然後有禮。禮，人之所履也。 履而泰，然後安，故受之以泰。泰者，通也。 此言「泰」所以次履也。程子曰：履得其所則舒泰，泰則安矣。 物不可以終通，故受之以否。 此言否所以次「泰」也。程子曰：通泰之極則必否。隔絕不相交通，否也。 物不可以終否，故受之以同人。 此言同人所以次否也。程子曰：天地不交則為否，上下相通則為同。人世之否，與人同力乃能濟。 與人同者，物必歸焉，故受之以大有。 此言大有所以次同人也。程子曰：與人同者，物之所歸。物之所歸，為「大有」之義。 有大者不可以盈，故受之以謙。 此言謙所以次大有也。程子曰：有既大，不可至於盈滿，必在謙損。 有大而能謙，必豫，故受之以豫。 此言豫所以次謙也。程子曰：有既大而能謙，則有豫樂。豫者，安和悅樂之義，承二卦之義而為次也。 豫必有隨，故受之以隨。 此言隨所以次豫也。程子曰：豫，悅之道，物之所隨。 以喜隨人者必有事，故受之以蠱。蠱者，事也。 此言蠱所以次隨也。程子曰：喜悅以隨於人者，必有事也。無事則何喜何隨？承二卦之義以為次。蠱非訓事，蠱乃有事也。 有事而後可大，故受之以臨。臨者，大也。 此言臨所以次蠱也。程子曰：韓康伯雲：可大之業，由事而生。二陽方長而盛大為臨。澄謂：因蠱之有事，而後有臨之盛大也。 物大然後可觀，故受之以觀。 此言觀所以次臨也。物之小者在下，視之而不見，必大而後可以觀也。以臨卦二陽之大，反易其體，則大者在上矣，故為在下四陰之所觀。 可觀而後有所合，故受之以噬嗑。嗑者，合也。 此言「噬嗑」所以次觀也。程子曰：既有所觀，然後有來合之者。 物不可以苟合而已，故受之以賁。賁者，飾也。 此言「賁」所以次噬嗑也。不執贄，則不可以成賓主之合；不受幣，則不可以成男女之合。程子曰：物之合，必有文飾也。 致飾然後亨則盡矣，故受之以剝；剝者，剝也。 此言剝所以次賁也。致其文飾，而百嘉聚會，則華美之極至矣盡矣。程子曰：極則必反，故賁終則剝也。 物不可以終盡剝，窮上反下，故受之以復。 此言復所以次剝也。程子曰：物無剝盡之理，故剝極則復。陽剝極於上，而復生於下，窮上而反下也。 復則不妄矣，故受之以無妄。 此言「無妄」所以次復也。程子曰：復者，反於道也。既復於道，則合正理而無妄 有。無妄然後可畜，故受之以大畜。 此言大畜所以次無妄也。程子曰：無妄則為有實，故可畜聚。 物畜然後可養，故受之以頤；頤者，養也。 此言「頤」所以次大畜也。程子曰：物既畜聚，則必有以養，無養則不能存息。項氏曰：需當物生之初，如兒之須乳，苖之須溉，故曰飲食之道。頤當畜聚之極，萬物交致其養，故曰「養也」。 不養則不可動，故受之以大過。 此言大過所以次頤也。程子曰：凡物養而後能成，成則能動，動則有過。 物不可以終過，故受之以坎；坎者，陷也。 此言坎所以次大過也。程子曰：過極則必陷， 陷必有所麗，故受之以離；離者，麗也。 此言離所以次坎也。程子曰：陷於險難之中，則必有所附麗。傳九之一章，凡四百九字。「故受之以履」下，舊本無「履者禮也」四字，韓注有之。今案王弼略例引此四字，蓋是後人誤以正文書作注字。否，備鄙切。觀，平聲。注填音田。上於、時掌切。之別，彼列切。豫樂音洛方。長，知兩切。坎難乃旦反。 有天地，然後有萬物；有萬物，然後有男女；有男女，然後有夫婦；有夫婦，然後有父子；有父子，然後有君臣；有君臣，然後有上下；有上下，然後禮義有所錯。 此言鹹所以為下經之首也。夫婦，謂鹹卦。先言天地、萬物、男女者，有夫婦之所由也；後言父子、君臣、上下者，有夫婦之所致也。有夫婦，則其所生為父子。由家而國，雖非父子，而君尊臣卑之分，如父子也；由國而天下，雖非君臣，而上貴下賤之分，如君臣也。禮義所以分別尊卑貴賤之等。錯，猶置也。乾、坤、鹹不出卦名者，以其為上下篇之首卦，特別異之。程子曰：天地，萬物之本；夫婦，人倫之始。所以上經首乾、坤，下經首鹹、恆也。 夫婦之道，不可以不久也，故受之以恆。恆者，久也。 此言「恆」所以次鹹也。程子曰：「鹹」，夫婦之道，夫婦終身不變者。 物不可以久居其所，故受之以遁；遁者，退也。 此言遁所以次恆也。程子曰：久則有去。 物不可以終遁，故受之以「大壯」。 此言「大壯」所以次「遁」也。程子曰：「遁」為違去之義，「壯」為進盛之義。遁者，陰長而陽遁。「大壯」，陽之壯盛也。衰則必盛，消息相須，故既遁則必壯。 物不可以終壯，故受之以晉；晉者，進也。 此言「晉」所以次「大壯」也。程子曰：物無壯而止之理，既盛壯則必進。 進必有所傷，故受之以「明夷」；「夷」者，傷也。 此言「明夷」所以次「晉」也。程子曰：進而不己，必有所傷。 傷於外者，必反其家，故受之以家人。 此言「家人」所以次「明夷」也。程子曰：傷困於外，則必反於內。 家道窮必乖，故受之以睽；「睽」者，乖也。 此言「暌」所以次家人也。程子曰：家道窮，則暌乖離散。 乖必有難，故受之以蹇；蹇者，難也。 此言「蹇」所以次「睽」也。程子曰：暌乖之時，必有蹇難。 物不可以終難，故受之以解。解者，緩也。 此言解所以次蹇也。程子曰：難極則必散。解者，散也。 緩必有所失，故受之以損。 此言「損」所以次解也。程子曰：緩縱則必有所失，失則損。 損而不已必益，故受之以益。 此言「益」所以次損也。程子曰：盛衰損益如循環。損極必益。 益而不已必決，故受之以夬；夬者，決也。 此言夬所以次益也。程子曰：理無常益，益之極必潰矣。 決必有遇，故受之以姤；姤者，遇也。 此言姤所以次夬也。程子曰：夬，判也。物之決判，則有遇合，不合則何遇？ 物相遇而後聚，故受之以萃；萃者，聚也。 此言萃所以次姤也。程子曰：物相會遇，必成群聚。 聚而上者謂之升，故受之以升。 此言升所以次萃也。程子曰：物之積聚而益高大，聚而上也，故為升。 升而不己必困，故受之以困。 此言困所以次升也。程子曰：升者，自下而上。自下升上，以力進也，不己必困矣。 困乎上者必反下，故受之以井。 此言井所以次困也。程子曰：上升不己也而困，則必反於下。物之在下者莫如井， 井道不可不革，故受之以革。 此言革所以次井也。程子曰：井之為物，存之則穢敗，易之則清潔，不可不革者也。 革物者莫若鼎，故受之以鼎。 此言鼎所以次「革」也。程子曰：鼎之為用，變腥而為熟，易堅而為柔。水火不可同處也，能使相合為用而不相害，是能革物也。 主器者莫若長子，故受之以震。震者，動也。 此言「震」所以次鼎也。程子曰：鼎者，器也。震為長男，傳國家、繼位號者也。故為主器之主，而繼鼎之後。 物不可以終動，止之，故受之以艮。艮者，止也。 此言艮所以次震也。程子曰：動靜相理，因靜則有動，動則有靜。物無常動之 物，不可以終止，故受之以漸。漸者，進也。 此言「漸」所以次「艮」也。程子曰：進以序為漸，今人以緩進為漸。進止必有進，止之所生亦進也；所反亦進也。 進必有所歸，故受之以歸妹。 此言歸妹所以次漸也。程子曰：進必有所至，故漸有歸義。項氏曰：晉之義，進而明也。明之極，必至於無進，故有所傷。漸之義，不急於進，其進以漸，故得其所歸也。 得其所歸者必大，故受之以豐；豐者，大也。 此言「豐」所以次「歸妹」也。程子曰：「物所歸聚，必成其大。」澄謂：臨之大，以其所臨之二陽為大；豐之大，以其卦名為盛大之義。 窮大者必失其居，故受之以旅。 此言「旅」所以次「豐」也。程子曰：「豐盛至於窮極，則必失其所安。」 旅而無所容，故受之以巽；巽者，入也。 此言「巽」所以次「旅」也。程子曰：羈旅親寡，非巽順何所取容？苟能巽順，雖旅困之中，何往而不能入？ 入而後說之，故受之以兌；兌者，說也。 此言「兌」所以次「巽」也。程子曰：物相入則相說。 說而後散之，故受之以渙。渙者，離也。 此言「渙」所以次「兌」也。程子曰：人之氣憂則結聚，說則舒散。 物不可以終離，故受之以節。 此言「節」所以次「渙」也。程子曰：物既離散，則當節止之。 節而信之，故受之以中孚。 此言「中孚」所以次「節」也。程子曰：節者，為之制節，使不得過越也。信而後能行，上能信守之，下則信從之，節而信之也。 有其信者必行之，故受之以小過。 此言「小過」所以次「中孚」也。項氏曰：有其信，猶書所謂「有其善」，言以此自負而居有之也。自恃其信者，其行必果而過於中。程子曰：「信則必行，行則過也。」澄謂：過者，行動而逾越之也。故大過雲「動」，小過雲「行」。凡行動未至其所為未及，既至其所為至，既至而又動又行，則為逾越其所至之地而過也。 有過物者必濟，故受之以既濟。 此言既濟所以次小過也。人卑，才智逾越於人為過。程子曰：能過於物，必可以濟。項氏曰：大過則逾越常理，故必至於陷。小過則或可濟事，故有濟而無陷也。 物不可窮也，故受之以未濟終焉。 此言未濟所以次既濟，而為六十四卦之終也。程子曰：既濟矣，物之窮也。物窮而不變，則無不己之理。易者變易而不窮也。既濟之後，受以未濟，則未窮也。",-1),a("p",null,"傳九之二章，凡五百二字。錯，七路切。難，乃旦切。解音蟹。而上，時掌切。長子，知兩切。說音曰。注之分，扶問切。分別、別異，並彼列切。陰長，知兩切。呂氏大圭曰：序卦之意，有以相因為序，如屯、蒙、需、訟是也。有以相反為序，如泰、否、同人是也。天地間不出相反相因而已。 易纂言卷十一。",-1)])])}const f=t(r,[["render",c]]);export{_ as __pageData,f as default};
